import{_ as n,C as o,o as s,c as r,j as t,a as i,G as d,a3 as l}from"./chunks/framework.Bvm_liKL.js";const b=JSON.parse('{"title":"FAQ","description":"The most common questions and fixes when using ICC-CE","frontmatter":{"title":"FAQ","description":"The most common questions and fixes when using ICC-CE"},"headers":[],"relativePath":"en/guide/faq.md","filePath":"en/guide/faq.md"}'),h={name:"en/guide/faq.md"};function p(c,e,g,u,m,f){const a=o("ArticleMetadata");return s(),r("div",null,[e[0]||(e[0]=t("h1",{id:"faq",tabindex:"-1"},[i("FAQ "),t("a",{class:"header-anchor",href:"#faq","aria-label":'Permalink to "FAQ"'},"​")],-1)),d(a),e[1]||(e[1]=l('<h2 id="installation-and-startup" tabindex="-1">Installation and startup <a class="header-anchor" href="#installation-and-startup" aria-label="Permalink to &quot;Installation and startup&quot;">​</a></h2><p><strong>Nothing happens on double click / the window flashes and disappears</strong> The usual cause is a missing <strong>.NET 6 Desktop Runtime</strong>. Download &quot;.NET Desktop Runtime 6.x&quot; from Microsoft and install the build matching your system architecture. If it still won&#39;t start, check the reports in <code>CrashLogs</code>.</p><p><strong>Antivirus flags it</strong> ICC-CE creates a transparent always-on-top window and reads touch input, which some security products misidentify. Download from the official release page and add an exclusion.</p><p><strong>32-bit or 64-bit?</strong> Use 64-bit on any modern device. Pick 32-bit only if your OS itself is 32-bit.</p><h2 id="drawing-and-display" tabindex="-1">Drawing and display <a class="header-anchor" href="#drawing-and-display" aria-label="Permalink to &quot;Drawing and display&quot;">​</a></h2><p><strong>Noticeable lag while writing</strong> Try, in order: make sure you are on the vendor&#39;s official device driver, enable hardware-accelerated ink rendering in settings, and close other GPU-heavy programs. On older hardware, lower the ink smoothing strength.</p><p><strong>Stroke width is uneven</strong> That is pressure sensitivity working. Turn off pressure response in settings for uniform strokes.</p><p><strong>My drawing snapped into a perfect shape</strong> Shape recognition kicked in. Disable it in settings, or configure it to require a long press.</p><p><strong>Multi-touch doesn&#39;t work</strong> Confirm the device supports multi-touch (a HID-compliant touch screen appears in Device Manager), then check that gestures are not disabled in settings.</p><h2 id="gestures-and-interaction" tabindex="-1">Gestures and interaction <a class="header-anchor" href="#gestures-and-interaction" aria-label="Permalink to &quot;Gestures and interaction&quot;">​</a></h2><p><strong>Two-finger zoom does nothing</strong> Check the master gesture switch and the zoom gesture switch in settings. Some older panels have touch drivers that swallow two-finger gestures; updating the driver fixes it.</p><p><strong>Too many accidental touches</strong> Enable palm rejection and increase the touch area threshold.</p><h2 id="powerpoint-integration" tabindex="-1">PowerPoint integration <a class="header-anchor" href="#powerpoint-integration" aria-label="Permalink to &quot;PowerPoint integration&quot;">​</a></h2><p><strong>No PowerPoint buttons during a slide show</strong> Make sure you use desktop PowerPoint and that COM calls are not blocked by security policy. See the <a href="/website/en/guide/ppt-guide">PowerPoint Guide</a>.</p><p><strong>Ink is not saved</strong> Check the auto-save switch and write permissions on the target directory.</p><p><strong>The add-in is installed but inactive</strong> Office may have auto-disabled it. Re-enable it under File → Options → Add-ins → Manage: Disabled Items.</p><h2 id="settings-and-data" tabindex="-1">Settings and data <a class="header-anchor" href="#settings-and-data" aria-label="Permalink to &quot;Settings and data&quot;">​</a></h2><p><strong>Settings reset after a restart</strong> Usually the app was killed rather than closed normally, so the config never reached disk. Exit properly. If the directory is read-only (lab restore environments), move the data directory to a writable partition.</p><p><strong>Syncing settings to other machines</strong> Copy <code>Settings.json</code> to the same location on the target machine — see <a href="/website/en/guide/files-and-data">Files &amp; Data Locations</a>.</p><p><strong>I broke my config</strong> Delete <code>Settings.json</code>; defaults are regenerated on next start.</p><h2 id="versions-and-updates" tabindex="-1">Versions and updates <a class="header-anchor" href="#versions-and-updates" aria-label="Permalink to &quot;Versions and updates&quot;">​</a></h2><p><strong>Which channel should I use?</strong><strong>Beta</strong> for daily use, <strong>Stable</strong> if you need maximum stability, and <strong>never Nightly in a real classroom</strong>. See <a href="/website/en/guide/installation">Installation &amp; Update Channels</a>.</p><p><strong>Downloads are slow or fail</strong> The download page picks the fastest route automatically. If it still fails, try another channel or download manually from the GitHub releases page.</p><p><strong>Can I go back to an older version?</strong> Yes. Use the Newer / Older buttons on the download page to reach the version you want. If a downgrade behaves oddly, back up and delete the settings file to regenerate it.</p><h2 id="reporting-problems" tabindex="-1">Reporting problems <a class="header-anchor" href="#reporting-problems" aria-label="Permalink to &quot;Reporting problems&quot;">​</a></h2><p>When opening an issue, please include: the ICC-CE version, your Windows version, reproduction steps, and the matching files from <code>Logs</code> and <code>CrashLogs</code>. The more complete the report, the faster the fix.</p>',26))])}const y=n(h,[["render",p]]);export{b as __pageData,y as default};
